hooks.command:
python3 -c "
import json, sys, re
d = json.load(sys.stdin)
path = d.get('tool_input', {}).get('file_path', '')
if re.search(r'(^|/)\.env(\.[a-zA-Z0-9_-]+)?$', path):
    print(json.dumps({
        'decision': 'block',
        'reason': f'Blocked: {path} looks like a secrets file. Edit it directly outside Claude Code if needed.',
        'hookSpecificOutput': {'hookEventName': 'PreToolUse', 'permissionDecision': 'deny', 'permissionDecisionReason': 'Editing .env files is blocked by project policy.'}
    }))
else:
    print(json.dumps({'continue': True}))
"
